WITH Src AS (SELECT * FROM order_items WHERE unit_price BETWEEN 200 AND 280), summary AS (SELECT CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END AS quantity_bucket, MAX(quantity) - MIN(quantity) AS quantity_range FROM Src GROUP BY CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END) SELECT quantity_bucket, quantity_range FROM summary ORDER BY quantity_bucket, quantity_range DESC LIMIT 10
